css:
.sl-footer-glass { font-family: var(--smartlearn-body-font, inherit); }
.sl-footer-glass .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-footer-glass .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-footer-glass.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-footer-glass .sl-border { border-color: var(--smartlearn-card-border) !important; }

.sl-footer-glass .sl-btn-primary {
    background-color: var(--smartlearn-btn-bg) !important;
    border-color: var(--smartlearn-btn-bg) !important;
    color: var(--smartlearn-btn-text, #ffffff) !important;
    transition: background-color 0.2s ease, box-shadow 0.2s ease;
}
.sl-footer-glass .sl-btn-primary:hover,
.sl-footer-glass .sl-btn-primary:focus-visible,
.sl-footer-glass .sl-btn-primary:active {
    background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)) !important;
    border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)) !important;
    color: var(--smartlearn-btn-text, #ffffff) !important;
    box-shadow: 0 4px 12px color-mix(in srgb, var(--smartlearn-primary) 30%, transparent) !important;
}

.sl-footer-glass .sl-bg-glow {
    z-index: 0;
    pointer-events: none;
    background: radial-gradient(circle at center, color-mix(in srgb, var(--smartlearn-primary) 15%, transparent) 0%, transparent 70%);
}
.sl-footer-glass .sl-glass-container {
    background-color: var(--smartlearn-card-bg);
    background-color: color-mix(in srgb, var(--smartlearn-card-bg) 75%, transparent);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
}
.sl-footer-glass .sl-footer-link { transition: color 0.2s ease; }
.sl-footer-glass .sl-footer-link:hover,
.sl-footer-glass .sl-footer-link:focus-visible {
    color: var(--smartlearn-primary) !important;
    text-decoration: underline !important;
}
.sl-footer-glass .sl-social-glass {
    min-width: 40px;
    min-height: 40px;
    background-color: var(--smartlearn-bg);
    background-color: color-mix(in srgb, var(--smartlearn-bg) 50%, transparent);
    transition: background-color 0.2s ease, border-color 0.2s ease, transform 0.2s ease;
}
.sl-footer-glass .sl-social-glass:hover,
.sl-footer-glass .sl-social-glass:focus-visible {
    background-color: var(--smartlearn-btn-bg) !important;
    border-color: var(--smartlearn-btn-bg) !important;
    transform: translateY(-3px);
}
.sl-footer-glass .sl-social-glass:hover i,
.sl-footer-glass .sl-social-glass:focus-visible i {
    color: var(--smartlearn-btn-text, #ffffff) !important;
}
.sl-footer-glass a:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
    .sl-footer-glass .sl-btn-primary,
    .sl-footer-glass .sl-footer-link,
    .sl-footer-glass .sl-social-glass { transition: none; }
    .sl-footer-glass .sl-social-glass:hover,
    .sl-footer-glass .sl-social-glass:focus-visible { transform: none; }
}
